{
  "name": "xArm协作机械臂",
  "name_en": "xArm collaborative robotic arm",
  "manufacturer": "UFACTORY",
  "description": "xArm协作机械臂是一种多关节机器人，用于实验室自动化中的样品转运、定位、抓取和重复操作任务。该设备可提供笛卡尔位置、关节状态、运行模式、告警、温度以及电机相关状态等运行信息，适合自动化操作与过程监测。",
  "description_en": "The xArm collaborative robotic arm is a multi-joint robot used in laboratory automation for sample transfer, positioning, gripping, and repetitive handling tasks. The device can report Cartesian position, joint status, operating mode, alarms, temperature, and motor-related states, making it suitable for automated operations and process monitoring.",
  "tag_hints": [
    "collaborative robot",
    "robot arm",
    "lab automation",
    "sample handling",
    "Cartesian positioning",
    "joint motion monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-register_report_callback",
      "description": "订阅机械臂综合状态上报",
      "description_en": "Subscribe to comprehensive robot status reports"
    },
    {
      "action_name": "auto-register_report_location_callback",
      "description": "订阅机械臂位置上报",
      "description_en": "Subscribe to robot location reports"
    },
    {
      "action_name": "auto-register_connect_changed_callback",
      "description": "订阅机械臂连接状态变化",
      "description_en": "Subscribe to robot connection state changes"
    },
    {
      "action_name": "auto-register_state_changed_callback",
      "description": "订阅机械臂运行状态变化",
      "description_en": "Subscribe to robot operating state changes"
    },
    {
      "action_name": "auto-register_mode_changed_callback",
      "description": "订阅机械臂模式变化",
      "description_en": "Subscribe to robot mode changes"
    },
    {
      "action_name": "auto-register_mtable_mtbrake_changed_callback",
      "description": "订阅机械臂电机使能与刹车状态变化",
      "description_en": "Subscribe to motor enable and brake state changes"
    },
    {
      "action_name": "auto-register_error_warn_changed_callback",
      "description": "订阅机械臂错误与警告变化",
      "description_en": "Subscribe to robot error and warning changes"
    },
    {
      "action_name": "auto-register_cmdnum_changed_callback",
      "description": "订阅机械臂指令编号变化",
      "description_en": "Subscribe to command number changes"
    },
    {
      "action_name": "auto-register_temperature_changed_callback",
      "description": "订阅机械臂温度变化",
      "description_en": "Subscribe to robot temperature changes"
    },
    {
      "action_name": "auto-register_count_changed_callback",
      "description": "订阅机械臂计数值变化",
      "description_en": "Subscribe to robot count value changes"
    },
    {
      "action_name": "auto-register_iden_progress_changed_callback",
      "description": "订阅机械臂辨识进度变化",
      "description_en": "Subscribe to identification progress changes"
    },
    {
      "action_name": "auto-register_feedback_callback",
      "description": "订阅机械臂反馈信息",
      "description_en": "Subscribe to robot feedback messages"
    },
    {
      "action_name": "auto-release_report_callback",
      "description": "取消订阅机械臂综合状态上报",
      "description_en": "Unsubscribe from comprehensive robot status reports"
    },
    {
      "action_name": "auto-release_report_location_callback",
      "description": "取消订阅机械臂位置上报",
      "description_en": "Unsubscribe from robot location reports"
    },
    {
      "action_name": "auto-release_connect_changed_callback",
      "description": "取消订阅机械臂连接状态变化",
      "description_en": "Unsubscribe from robot connection state changes"
    },
    {
      "action_name": "auto-release_state_changed_callback",
      "description": "取消订阅机械臂运行状态变化",
      "description_en": "Unsubscribe from robot operating state changes"
    },
    {
      "action_name": "auto-release_mode_changed_callback",
      "description": "取消订阅机械臂模式变化",
      "description_en": "Unsubscribe from robot mode changes"
    },
    {
      "action_name": "auto-release_mtable_mtbrake_changed_callback",
      "description": "取消订阅机械臂电机使能与刹车状态变化",
      "description_en": "Unsubscribe from motor enable and brake state changes"
    },
    {
      "action_name": "auto-release_error_warn_changed_callback",
      "description": "取消订阅机械臂错误与警告变化",
      "description_en": "Unsubscribe from robot error and warning changes"
    },
    {
      "action_name": "auto-release_cmdnum_changed_callback",
      "description": "取消订阅机械臂指令编号变化",
      "description_en": "Unsubscribe from command number changes"
    },
    {
      "action_name": "auto-release_temperature_changed_callback",
      "description": "取消订阅机械臂温度变化",
      "description_en": "Unsubscribe from robot temperature changes"
    },
    {
      "action_name": "auto-release_count_changed_callback",
      "description": "取消订阅机械臂计数值变化",
      "description_en": "Unsubscribe from robot count value changes"
    },
    {
      "action_name": "auto-release_iden_progress_changed_callback",
      "description": "取消订阅机械臂辨识进度变化",
      "description_en": "Unsubscribe from identification progress changes"
    },
    {
      "action_name": "auto-release_feedback_callback",
      "description": "取消订阅机械臂反馈信息",
      "description_en": "Unsubscribe from robot feedback messages"
    }
  ]
}

